/** कर्णेल_मान 안의 연결형 बाइट_मान प्रवाह_मान. Ethernet/TCP 패킷 스택이 아닌 루프백 socket तह_मान. */
public final class प्रवाह_सञ्जाल {
    static int[] स्थिति_मान = new int[16], पोर्ट_मान = new int[16], 짝 = new int[16], समान_पोर्ट = new int[16], 대기 = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], लगत = new int[16 * 1024];
    static int अर्को_वस्तु = 50000;
    static int रुजू_गर्नुहोस्(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && स्थिति_मान[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int 접속번호) { for (int लुप_अनुक्रमणिका = 0; लुप_अनुक्रमणिका < 16; लुप_अनुक्रमणिका++) if (स्थिति_मान[लुप_अनुक्रमणिका] != 0 && 묶임[लुप_अनुक्रमणिका] != 0 && पोर्ट_मान[लुप_अनुक्रमणिका] == 접속번호) return true; return false; }
    public static int सिर्जना_प्रविष्टि() {
        for (int लुप_अनुक्रमणिका = 0; लुप_अनुक्रमणिका < 16; लुप_अनुक्रमणिका++) if (स्थिति_मान[लुप_अनुक्रमणिका] == 0) { स्थिति_मान[लुप_अनुक्रमणिका] = 1; समान_पोर्ट[लुप_अनुक्रमणिका] = पोर्ट_मान[लुप_अनुक्रमणिका] = 앞[लुप_अनुक्रमणिका] = 수[लुप_अनुक्रमणिका] = 대기[लुप_अनुक्रमणिका] = 묶임[लुप_अनुक्रमणिका] = 0; 짝[लुप_अनुक्रमणिका] = -1; return लुप_अनुक्रमणिका + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int 접속번호) {
        int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (स्थिति_मान[लुप_अनुक्रमणिका] != 1 || 접속번호 < 0 || 접속번호 > 65535) return -22;
        if (접속번호 == 0) { do { 접속번호 = अर्को_वस्तु++; if (अर्को_वस्तु > 65535) अर्को_वस्तु = 50000; } while (사용중(접속번호)); }
        if (사용중(접속번호)) return -98; पोर्ट_मान[लुप_अनुक्रमणिका] = 접속번호; 묶임[लुप_अनुक्रमणिका] = 1; स्थिति_मान[लुप_अनुक्रमणिका] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9; if (स्थिति_मान[लुप_अनुक्रमणिका] != 2 || 연결대기한도 < 1) return -22; स्थिति_मान[लुप_अनुक्रमणिका] = 3; return 0; }
    public static int जडान(int 열린파일번호, int 통신주소, int 접속번호) {
        int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (접속번호 < 1 || 접속번호 > 65535 || स्थिति_मान[लुप_अनुक्रमणिका] > 2) return -22;
        int 수신쪽 = -1; for (int भित्री_जोड्नी_राख्नुहोस् = 0; भित्री_जोड्नी_राख्नुहोस् < 16; भित्री_जोड्नी_राख्नुहोस्++) if (स्थिति_मान[भित्री_जोड्नी_राख्नुहोस्] == 3 && पोर्ट_मान[भित्री_जोड्नी_राख्नुहोस्] == 접속번호) 수신쪽 = भित्री_जोड्नी_राख्नुहोस्;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int भित्री_जोड्नी_राख्नुहोस् = 0; भित्री_जोड्नी_राख्नुहोस् < 16; भित्री_जोड्नी_राख्नुहोस्++) if (대기[भित्री_जोड्नी_राख्नुहोस्] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (स्थिति_मान[लुप_अनुक्रमणिका] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = सिर्जना_प्रविष्टि(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        स्थिति_मान[लुप_अनुक्रमणिका] = स्थिति_मान[다른번호] = 4; 짝[लुप_अनुक्रमणिका] = 다른번호; 짝[다른번호] = लुप_अनुक्रमणिका; पोर्ट_मान[다른번호] = 접속번호; समान_पोर्ट[लुप_अनुक्रमणिका] = 접속번호; समान_पोर्ट[다른번호] = पोर्ट_मान[लुप_अनुक्रमणिका]; 대기[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int स्वीकार्नुहोस्_जडान(int 열린파일번호) { int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9; if (स्थिति_मान[लुप_अनुक्रमणिका] != 3) return -22; for (int भित्री_जोड्नी_राख्नुहोस् = 0; भित्री_जोड्नी_राख्नुहोस् < 16; भित्री_जोड्नी_राख्नुहोस्++) if (स्थिति_मान[भित्री_जोड्नी_राख्नुहोस्] != 0 && 대기[भित्री_जोड्नी_राख्नुहोस्] == लुप_अनुक्रमणिका + 1) { 대기[भित्री_जोड्नी_राख्नुहोस्] = 0; return भित्री_जोड्नी_राख्नुहोस् + 40; } return -11; }
    public static int लेख्नुहोस्(int 열린파일번호, int 항목수) {
        int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9; if (स्थिति_मान[लुप_अनुक्रमणिका] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int भित्री_जोड्नी_राख्नुहोस् = 짝[लुप_अनुक्रमणिका]; if (भित्री_जोड्नी_राख्नुहोस् < 0) return -32; int 총수 = 1024 - 수[भित्री_जोड्नी_राख्नुहोस्]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int तुलना_राख्नुहोस् = 0; तुलना_राख्नुहोस् < 총수; तुलना_राख्नुहोस्++) लगत[भित्री_जोड्नी_राख्नुहोस् * 1024 + (앞[भित्री_जोड्नी_राख्नुहोस्] + 수[भित्री_जोड्नी_राख्नुहोस्] + तुलना_राख्नुहोस्) % 1024] = 되돌림망.फरवार्ड_मान[तुलना_राख्नुहोस्]; 수[भित्री_जोड्नी_राख्नुहोस्] += 총수; return 총수;
    }
    public static int पढनुहोस्(int 열린파일번호, int 항목수) {
        int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9; if (स्थिति_मान[लुप_अनुक्रमणिका] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[लुप_अनुक्रमणिका] == 0) return 짝[लुप_अनुक्रमणिका] < 0 ? 0 : -11; if (항목수 > 수[लुप_अनुक्रमणिका]) 항목수 = 수[लुप_अनुक्रमणिका];
        for (int तुलना_राख्नुहोस् = 0; तुलना_राख्नुहोस् < 항목수; तुलना_राख्नुहोस्++) 되돌림망.फरवार्ड_मान[तुलना_राख्नुहोस्] = लगत[लुप_अनुक्रमणिका * 1024 + (앞[लुप_अनुक्रमणिका] + तुलना_राख्नुहोस्) % 1024]; 앞[लुप_अनुक्रमणिका] = (앞[लुप_अनुक्रमणिका] + 항목수) % 1024; 수[लुप_अनुक्रमणिका] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); return लुप_अनुक्रमणिका < 0 ? -9 : पोर्ट_मान[लुप_अनुक्रमणिका]; }
    public static int 상대창구읽기(int 열린파일번호) { int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); return लुप_अनुक्रमणिका < 0 ? -9 : समान_पोर्ट[लुप_अनुक्रमणिका]; }
    public static int बन्दगर्नुहोस्(int 열린파일번호) {
        int लुप_अनुक्रमणिका = रुजू_गर्नुहोस्(열린파일번호); if (लुप_अनुक्रमणिका < 0) return -9;
        if (स्थिति_मान[लुप_अनुक्रमणिका] == 3) for (int भित्री_जोड्नी_राख्नुहोस् = 0; भित्री_जोड्नी_राख्नुहोस् < 16; भित्री_जोड्नी_राख्नुहोस्++) if (대기[भित्री_जोड्नी_राख्नुहोस्] == लुप_अनुक्रमणिका + 1) { if (짝[भित्री_जोड्नी_राख्नुहोस्] >= 0) 짝[짝[भित्री_जोड्नी_राख्नुहोस्]] = -1; स्थिति_मान[भित्री_जोड्नी_राख्नुहोस्] = 대기[भित्री_जोड्नी_राख्नुहोस्] = 묶임[भित्री_जोड्नी_राख्नुहोस्] = 0; }
        if (짝[लुप_अनुक्रमणिका] >= 0) 짝[짝[लुप_अनुक्रमणिका]] = -1; स्थिति_मान[लुप_अनुक्रमणिका] = 묶임[लुप_अनुक्रमणिका] = 수[लुप_अनुक्रमणिका] = 대기[लुप_अनुक्रमणिका] = 0; return 0;
    }
}
